verus! {
    /// Deep‐clones a vector of u64s.
    ///
    /// The returned vector has the same length as `arr`, and
    /// for each valid index `i`, `copied[i] == arr[i]`.  Because
    /// we copy each element, the result is independent of the
    /// original: subsequent modifications to `arr` do not affect `copied`.
    fn list_deep_clone(arr: &Vec<u64>) -> (copied: Vec<u64>)
        ensures
            copied.len() == arr.len(),
            forall |i: usize| i < arr.len() ==> copied[i] == arr[i],
    {
        let mut copied: Vec<u64> = Vec::new();
        let mut idx: usize = 0;
        // Loop to copy each element one by one
        while idx < arr.len()
            invariant
                // index stays within bounds
                idx <= arr.len(),
                // we have copied exactly `idx` elements so far
                copied.len() == idx,
                // and those copied elements match the original
                forall |j: usize| j < idx ==> copied[j] == arr[j],
            decreases arr.len() - idx,
        {
            // push the next element
            copied.push(arr[idx]);
            idx = idx + 1;
        }
        copied
    }
}

